-- Catálogo bilíngue, lote 1/10. Execute após 202609300001_vocabulary_categories.sql.
-- Reexecutável: atualiza também definition_pt e example_pt das palavras já importadas.
begin;
do $$ begin if exists (select 1 from (select unnest(array['arts', 'business', 'food', 'general-vocabulary', 'health', 'law', 'politics', 'science', 'sports', 'technical', 'technology']) as slug) required left join public.vocabulary_categories c using (slug) where c.id is null) then raise exception 'Categorias do catálogo ausentes'; end if; end $$;
insert into public.vocabulary_words (word,translation,definition_en,definition_pt,example_en,example_pt,cefr_level,word_type,category_id,frequency_rank)
select v.word,v.translation,v.definition_en,v.definition_pt,v.example_en,v.example_pt,v.cefr_level,v.word_type,c.id,v.frequency_rank
from jsonb_to_recordset($catalog$
[
{"word":"you","translation":"você","definition_en":"Used as the subject of a verb when addressing one or more people directly, regardless of formality or number in Modern English.","definition_pt":"Usado como o sujeito de um verbo ao se dirigir diretamente a uma ou mais pessoas, independentemente da formalidade ou número em inglês moderno.","example_en":"You are very kind.","example_pt":"Você é muito gentil.","cefr_level":"A1","word_type":"pronoun","category_slug":"general-vocabulary","frequency_rank":1},
{"word":"to","translation":"para","definition_en":"Indicates movement or orientation in the direction of a place, person, or object","definition_pt":"Indica movimento ou orientação na direção de um lugar, pessoa ou objeto.","example_en":"She went to the store","example_pt":"Ela foi à loja.","cefr_level":"A1","word_type":"preposition","category_slug":"general-vocabulary","frequency_rank":4},
{"word":"it","translation":"isso","definition_en":"Used as the subject or object of a verb to refer to an inanimate object, an animal, a baby of unspecified gender, or an abstract idea that has been mentioned or is clear from context.","definition_pt":"Usado como sujeito ou objeto de um verbo para se referir a um objeto inanimado, um animal, um bebê de gênero não especificado, ou uma ideia abstrata que foi mencionada ou é clara do contexto.","example_en":"I bought a new phone. It works perfectly.","example_pt":"Comprei um telefone novo. Funciona perfeitamente.","cefr_level":"A1","word_type":"pronoun","category_slug":"general-vocabulary","frequency_rank":7},
{"word":"that","translation":"aquilo","definition_en":"Used to refer to a specific thing, person, idea, or situation that is distant in space, time, or context from the speaker, replacing a noun to avoid repetition while pointing it out.","definition_pt":"Usado para se referir a uma coisa específica, pessoa, ideia, ou situação que é distante no espaço, tempo ou contexto do falante, substituindo um substantivo para evitar a repetição enquanto apontava para ele.","example_en":"Look at the big building over there. That is the new library.","example_pt":"Olhe para o prédio grande ali. Essa é a nova biblioteca.","cefr_level":"A1","word_type":"pronoun","category_slug":"general-vocabulary","frequency_rank":9},
{"word":"of","translation":"de","definition_en":"Used to show that something belongs to someone or something, or to express a connection, attribute, or relationship between two nouns.","definition_pt":"Usado para mostrar que algo pertence a alguém ou algo, ou para expressar uma conexão, atributo, ou relação entre dois substantivos.","example_en":"The cover of the book is torn.","example_pt":"A capa do livro está rasgada.","cefr_level":"A1","word_type":"preposition","category_slug":"general-vocabulary","frequency_rank":11},
{"word":"in","translation":"em","definition_en":"used to show that something is enclosed or surrounded by something else","definition_pt":"Costumava mostrar que algo está fechado ou cercado por outra coisa.","example_en":"The keys are in my bag.","example_pt":"As chaves estão na minha bolsa.","cefr_level":"A1","word_type":"preposition","category_slug":"general-vocabulary","frequency_rank":13},
{"word":"we","translation":"nós","definition_en":"Used as the subject of a verb when the speaker refers to themselves together with one or more other people, indicating a group that includes the speaker.","definition_pt":"Usado como o sujeito de um verbo quando o falante se refere a si mesmo junto com uma ou mais pessoas, indicando um grupo que inclui o falante.","example_en":"We are going to the cinema tonight.","example_pt":"Vamos ao cinema hoje à noite.","cefr_level":"A1","word_type":"pronoun","category_slug":"general-vocabulary","frequency_rank":15},
{"word":"he","translation":"ele","definition_en":"Used as the subject of a verb to refer to a male person or animal that has already been mentioned or is clearly identified in the context.","definition_pt":"Usado como sujeito de um verbo para se referir a um homem ou animal que já foi mencionado ou claramente identificado no contexto.","example_en":"He is my brother.","example_pt":"Ele é meu irmão.","cefr_level":"A1","word_type":"pronoun","category_slug":"general-vocabulary","frequency_rank":18},
{"word":"for","translation":"por","definition_en":"Used to show the purpose of an action, object, or plan — what something is meant to do or achieve.","definition_pt":"Costumava mostrar o propósito de uma ação, objeto ou plano, o que algo é feito para fazer ou alcançar.","example_en":"This button is for turning on the light.","example_pt":"Este botão é para acender a luz.","cefr_level":"A1","word_type":"preposition","category_slug":"general-vocabulary","frequency_rank":19},
{"word":"on","translation":"sobre","definition_en":"Indicates the position of something touching or covering the surface of another thing.","definition_pt":"Indica a posição de algo que toca ou cobre a superfície de outra coisa.","example_en":"a picture on a wall","example_pt":"uma foto em uma parede","cefr_level":"A1","word_type":"preposition","category_slug":"general-vocabulary","frequency_rank":21},
{"word":"have","translation":"ter","definition_en":"To possess, own, or hold something.","definition_pt":"Possuir, possuir ou segurar algo.","example_en":"I have a new car.","example_pt":"Tenho um carro novo.","cefr_level":"A1","word_type":"verb","category_slug":"general-vocabulary","frequency_rank":22},
{"word":"do","translation":"fazer","definition_en":"To carry out or complete an activity, task, or specific piece of work.","definition_pt":"Para realizar ou completar uma atividade, tarefa ou trabalho específico.","example_en":"I have so much work to before the deadline tomorrow morning.","example_pt":"Tenho muito trabalho para fazer antes do prazo amanhã de manhã.","cefr_level":"A1","word_type":"verb","category_slug":"general-vocabulary","frequency_rank":24},
{"word":"not","translation":"não","definition_en":"Used to form the negative of verbs, adjectives, or other adverbs.","definition_pt":"Usado para formar o negativo de verbos, adjetivos ou outros advérbios.","example_en":"I do not understand the question.","example_pt":"Não entendo a pergunta.","cefr_level":"A1","word_type":"adverb","category_slug":"general-vocabulary","frequency_rank":28},
{"word":"be","translation":"ser","definition_en":"Used to indicate that something exists or to state a fact about something or someone.","definition_pt":"Costumava indicar que algo existe ou que diz um fato sobre algo ou alguém.","example_en":"To be or not to be, that is the question.","example_pt":"Ser ou não ser, essa é a questão.","cefr_level":"A1","word_type":"verb","category_slug":"general-vocabulary","frequency_rank":29},
{"word":"know","translation":"saber","definition_en":"To have information in your mind as a result of experience or learning.","definition_pt":"Ter informações em sua mente como resultado de experiência ou aprendizagem.","example_en":"I know the answer to that question.","example_pt":"Eu sei a resposta para essa pergunta.","cefr_level":"A1","word_type":"verb","category_slug":"general-vocabulary","frequency_rank":33},
{"word":"can","translation":"poder","definition_en":"Expresses that the subject possesses the physical, mental, or learned skill to perform an action in the present or as a general truth. This is the most fundamental use of 'can', indicating inherent or acquired capacity. Contrasts with 'could' which refers to past ability or hypothetical capacity.","definition_pt":"Expressa que o sujeito possui a habilidade física, mental ou aprendida para realizar uma ação no presente ou como uma verdade geral. Este é o uso mais fundamental de 'pode', indicando capacidade inerente ou adquirida. Contraste com \"poderia\", que se refere à capacidade passada ou hipotética.","example_en":"She can speak three languages fluently.","example_pt":"Ela fala três línguas fluentemente.","cefr_level":"A1","word_type":"verb","category_slug":"general-vocabulary","frequency_rank":34},
{"word":"with","translation":"com","definition_en":"Used to indicate that someone or something is in the company of, alongside, or in association with another person, thing, or group.","definition_pt":"Costumava indicar que alguém ou algo está na companhia de, ao lado, ou em associação com outra pessoa, coisa, ou grupo.","example_en":"She went to the cinema with her friends.","example_pt":"Ela foi ao cinema com os amigos.","cefr_level":"A1","word_type":"preposition","category_slug":"general-vocabulary","frequency_rank":35},
{"word":"all","translation":"todo","definition_en":"Used to emphasize the completeness of an action or state.","definition_pt":"Costumava enfatizar a integridade de uma ação ou estado.","example_en":"The cake was all eaten by the children.","example_pt":"O bolo foi todo comido pelas crianças.","cefr_level":"A2","word_type":"adverb","category_slug":"general-vocabulary","frequency_rank":37},
{"word":"so","translation":"tão","definition_en":"Used to indicate that something has a particular quality to a high degree, often followed by 'that' to show a result.","definition_pt":"Costumava indicar que algo tem uma qualidade particular em alto grau, muitas vezes seguido por \"isso\" para mostrar um resultado.","example_en":"The movie was so boring that I fell asleep.","example_pt":"O filme foi tão chato que eu adormeci.","cefr_level":"A2","word_type":"adverb","category_slug":"general-vocabulary","frequency_rank":38},
{"word":"just","translation":"bem","definition_en":"Used to emphasize that something is exactly as stated.","definition_pt":"Costumava enfatizar que algo é exatamente como dito.","example_en":"That is just what I needed.","example_pt":"Era exatamente o que eu precisava.","cefr_level":"A1","word_type":"adverb","category_slug":"general-vocabulary","frequency_rank":39},
{"word":"there","translation":"ali","definition_en":"Used to refer to a place that has already been mentioned or is known.","definition_pt":"Costumava se referir a um lugar que já foi mencionado ou conhecido.","example_en":"The book is over there on the table.","example_pt":"O livro está ali na mesa.","cefr_level":"A1","word_type":"adverb","category_slug":"general-vocabulary","frequency_rank":40},
{"word":"here","translation":"aqui","definition_en":"Indicates the location where the speaker is or the place immediately close to them.","definition_pt":"Indica o local onde o alto-falante está ou o lugar imediatamente perto deles.","example_en":"Put the book here on the table.","example_pt":"Coloque o livro aqui na mesa.","cefr_level":"A1","word_type":"adverb","category_slug":"general-vocabulary","frequency_rank":41},
{"word":"they","translation":"eles","definition_en":"Used as the subject of a verb to refer to two or more people, animals, or things that have already been mentioned or are clearly identified in the context.","definition_pt":"Usado como o sujeito de um verbo para se referir a duas ou mais pessoas, animais, ou coisas que já foram mencionadas ou são claramente identificadas no contexto.","example_en":"My parents are doctors. They work at the same hospital.","example_pt":"Meus pais são médicos. Eles trabalham no mesmo hospital.","cefr_level":"A1","word_type":"pronoun","category_slug":"general-vocabulary","frequency_rank":42},
{"word":"like","translation":"como","definition_en":"Used to show that one person, thing, or action has qualities, appearance, or characteristics similar to another.","definition_pt":"Costumava mostrar que uma pessoa, coisa ou ação tem qualidades, aparência ou características semelhantes a outra.","example_en":"She looks like her mother.","example_pt":"Ela se parece com a mãe.","cefr_level":"A1","word_type":"preposition","category_slug":"general-vocabulary","frequency_rank":43},
{"word":"she","translation":"ela","definition_en":"Used as the subject of a verb to refer to a female person or animal that has already been mentioned or is clearly identified in the context.","definition_pt":"Usado como sujeito de um verbo para se referir a uma pessoa feminina ou animal que já foi mencionado ou é claramente identificado no contexto.","example_en":"She is a talented musician.","example_pt":"Ela é uma musicista talentosa.","cefr_level":"A1","word_type":"pronoun","category_slug":"general-vocabulary","frequency_rank":46},
{"word":"go","translation":"ir","definition_en":"To move from one place to another; to travel.","definition_pt":"Para ir de um lugar para outro, para viajar.","example_en":"I go to school every day.","example_pt":"Vou à escola todos os dias.","cefr_level":"A1","word_type":"verb","category_slug":"general-vocabulary","frequency_rank":47},
{"word":"if","translation":"se","definition_en":"Used to talk about real or possible situations in the present or future. The if-clause describes a realistic condition, and the main clause shows the likely result. This is the most common use of \"if\" (first conditional and zero conditional).","definition_pt":"Costumava falar sobre situações reais ou possíveis no presente ou futuro. A cláusula if-clause descreve uma condição realista, e a cláusula principal mostra o resultado provável. Este é o uso mais comum de \"se\" (primeiro condicional e zero condicional).","example_en":"If it rains tomorrow, we will stay at home.","example_pt":"Se chover amanhã, ficaremos em casa.","cefr_level":"A1","word_type":"conjunction","category_slug":"general-vocabulary","frequency_rank":48},
{"word":"right","translation":"direito","definition_en":"A moral or legal entitlement to have or do something.","definition_pt":"Um direito moral ou legal de ter ou fazer algo.","example_en":"Everyone has the right to free speech.","example_pt":"Todos têm direito à liberdade de expressão.","cefr_level":"A2","word_type":"noun","category_slug":"general-vocabulary","frequency_rank":49},
{"word":"out","translation":"fora","definition_en":"Used to describe something that is outside of a place, not inside, or not present.","definition_pt":"Costumava descrever algo que está fora de um lugar, não dentro, ou não presente.","example_en":"He is out of the office today.","example_pt":"Ele está fora do escritório hoje.","cefr_level":"A1","word_type":"adjective","category_slug":"general-vocabulary","frequency_rank":50},
{"word":"about","translation":"por volta de","definition_en":"Used to indicate an imprecise but fairly close estimate of a quantity or number.","definition_pt":"Costumava indicar uma estimativa imprecisa, mas bastante próxima de uma quantidade ou número.","example_en":"There were about fifty people at the party.","example_pt":"Havia cerca de 50 pessoas na festa.","cefr_level":"A1","word_type":"adverb","category_slug":"general-vocabulary","frequency_rank":51},
{"word":"up","translation":"acima","definition_en":"Used to show movement from a lower position to a higher one, often involving climbing, ascending, or rising along a vertical or sloped surface.","definition_pt":"Costumava mostrar movimento de uma posição mais baixa para uma mais alta, muitas vezes envolvendo escalada, ascensão, ou elevação ao longo de uma superfície vertical ou inclinada.","example_en":"They climbed up the mountain.","example_pt":"Subiram a montanha.","cefr_level":"A1","word_type":"preposition","category_slug":"general-vocabulary","frequency_rank":52},
